        dfs(digits, new StringBuilder(), 0);
        return ans;
    }

    private void dfs(String digits, StringBuilder sb, int len) {
        if (len == digits.length()) {
            ans.add(sb.toString());
            return;
        }

        for (char c : map[digits.charAt(len) - '0'].toCharArray()) {
            sb.append(c);
            dfs(digits, sb, len + 1);
            sb.deleteCharAt(sb.length() - 1);
